/// <summary>
/// Everything a task needs while it runs: the environment, the secrets passed to the service
/// call, a record counter and logging into <c>BDRMessageLog</c>.
/// </summary>
/// <remarks>
/// Messages are written on a separate connection, so they stay in the log even when the task
/// fails and its own transaction is rolled back.
/// </remarks>
public final class BDRTaskContext
{
    private BDREnvironment environment;
    private RecId jobHistoryRecId;
    private RecId taskHistoryRecId;
    private BDRTaskTypeName taskTypeName;
    private Map secrets;
    private BDRRecordsAffected recordsAffected;
    private boolean errorsFound;
    private str lastErrorMessage;
}

Method.Source:
    /// <summary>
    /// Creates the context for one task of a job.
    /// </summary>
    /// <param name = "_environment">The environment the job runs for.</param>
    /// <param name = "_jobHistoryRecId">The job.</param>
    /// <param name = "_taskHistoryRecId">The task history record of this task.</param>
    /// <param name = "_taskTypeName">The task type.</param>
    /// <param name = "_secrets">Secrets by name, may be null.</param>
    /// <returns>The context.</returns>
    public static BDRTaskContext construct(BDREnvironment _environment, RecId _jobHistoryRecId, RecId _taskHistoryRecId, BDRTaskTypeName _taskTypeName, Map _secrets)
    {
        BDRTaskContext context = new BDRTaskContext();

        context.environment = _environment;
        context.jobHistoryRecId = _jobHistoryRecId;
        context.taskHistoryRecId = _taskHistoryRecId;
        context.taskTypeName = _taskTypeName;
        context.secrets = _secrets ? _secrets : new Map(Types::String, Types::String);

        return context;
    }

/// <summary>
/// Checks whether a secret was passed to the service call.
/// </summary>
/// <param name = "_name">The secret name.</param>
/// <returns>True if the secret is available.</returns>
public boolean hasSecret(BDRSecretName _name)
{
    return _name && secrets.exists(_name);
}

    /// <summary>
    /// Returns a secret passed to the service call. Secrets are never stored in the database.
    /// </summary>
    /// <param name = "_name">The secret name.</param>
    /// <returns>The secret value.</returns>
    public str secret(BDRSecretName _name)
    {
        if (!this.hasSecret(_name))
        {
            throw error(strFmt("@BDR:ErrSecretMissing", _name));
        }

        return secrets.lookup(_name);
    }

/// <summary>
/// Starts counting again, for example before a task is retried after a deadlock.
/// </summary>
public void resetRecordsAffected()
{
    recordsAffected = 0;
}

public void logError(str _message)
{
    errorsFound = true;
    lastErrorMessage = _message;
    this.log(BDRMessageType::Error, _message);
}

/// <summary>
/// Writes a message into the message log of the job.
/// </summary>
/// <param name = "_type">Info, warning or error.</param>
/// <param name = "_message">The message.</param>
public void log(BDRMessageType _type, str _message)
{
    BDRTaskContext::writeMessage(jobHistoryRecId, taskHistoryRecId, taskTypeName, _type, _message);
}

    /// <summary>
    /// Writes a message on a separate connection so it survives a rollback of the caller.
    /// </summary>
    public static void writeMessage(RecId _jobHistoryRecId, RecId _taskHistoryRecId, BDRTaskTypeName _taskTypeName, BDRMessageType _type, str _message)
    {
        UserConnection connection = new UserConnection();
        BDRMessageLog messageLog;

        messageLog.setConnection(connection);

        connection.ttsbegin();

        messageLog.JobHistory = _jobHistoryRecId;
        messageLog.TaskHistory = _taskHistoryRecId;
        messageLog.TaskTypeName = _taskTypeName;
        messageLog.MessageType = _type;
        messageLog.Message = subStr(_message, 1, 1000);
        messageLog.insert();

        connection.ttscommit();
        connection.finalize();
    }
